package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

public class TypeParser_parseType_TriageGen1Test {

    private TypeFactory typeFactory;
    private TypeParser typeParser;
    private MyTokenizer tokens;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
        // We use spy to bypass protected methods findClass and parseTypes 
        // and control the flow for branch coverage
        typeParser = spy(new TypeParser(typeFactory));
        tokens = mock(MyTokenizer.class);
    }

    @Test
    public void testParseType_UnexpectedEndOfString() {
        when(tokens.hasMoreTokens()).thenReturn(false);

        try {
            typeParser.parseType(tokens);
        } catch (IllegalArgumentException e) {
            // Success: exception thrown by _problem via the first if block
            return;
        }
        throw new AssertionError("Expected IllegalArgumentException due to unexpected end-of-string");
    }

    @Test
    public void testParseType_SimpleNonGenericType() {
        Class<?> expectedClass = String.class;

        // Setup: tokens has one token (the class name) then ends
        when(tokens.hasMoreTokens()).thenReturn(true, false);
        when(tokens.nextToken()).thenReturn("java.lang.String");

        // Mock findClass to return our class
        doReturn(expectedClass).when(typeParser).findClass(eq("java.lang.String"), any());

        JavaType result = typeParser.parseType(tokens);

        assertNotNull(result);
        assertEquals(expectedClass, result.getRawClass());
    }

    @Test
    public void testParseType_GenericType() {
        Class<?> baseClass = java.util.List.class;
        Class<?> paramClass = java.lang.Integer.class;
        JavaType paramType = typeFactory.constructType(paramClass);

        // Setup: tokens -> "List" -> "<" -> (parseTypes) -> ">"
        // 1. hasMoreTokens (true) for base class
        // 2. hasMoreTokens (true) for '<'
        // 3. hasMoreTokens (false) after tokens.nextToken() returns '<' 
        //    (simulating end of generic list for simplicity in this mock sequence)
        when(tokens.hasMoreTokens()).thenReturn(true, true, false);
        when(tokens.nextToken()).thenReturn("java.util.List", "<");

        doReturn(baseClass).when(typeParser).findClass(eq("java.util.List"), any());

        // Mock parseTypes to return a list containing Integer
        doReturn(Collections.singletonList(paramType)).when(typeParser).parseTypes(tokens);

        JavaType result = typeParser.parseType(tokens);

        assertNotNull(result);
        assertEquals(baseClass, result.getRawClass());
        assertEquals(1, result.getParametricTypeCount());
        assertEquals(paramType, result.getParametricType(0));
    }

    @Test
    public void testParseType_CommaOrClosingBracketBranch() {
        Class<?> baseClass = String.class;

        // Setup: tokens -> "String" -> "," (or ">")
        // This tests the branch where tokens.hasMoreTokens() is true but token is NOT "<"
        // The token should be pushed back.
        when(tokens.hasMoreTokens()).thenReturn(true, true, false);
        when(tokens.nextToken()).thenReturn("java.lang.String", ",");

        doReturn(baseClass).when(typeParser).findClass(eq("java.lang.String"), any());

        JavaType result = typeParser.parseType(tokens);

        assertNotNull(result);
        assertEquals(baseClass, result.getRawClass());
        // Verify pushBack was called for the comma/bracket
        Mockito.verify(tokens).pushBack(",");
    }
}
